import org.aspectj.lang.annotation.Aspect;
import java.util.List;

@Aspect
public class MyAspect {
    List state; // bad, not private
    private List ok;
}

@Aspect("perthis(execution(* com.xyz.Service.*(..)))")
public class PerThisAspect {
    protected List state; // bad, the advised target is typically a singleton, so shared as well
    private List ok;
}

import org.aspectj.lang.annotation.Aspect;
import org.springframework.context.annotation.Scope;
import org.springframework.beans.factory.config.ConfigurableBeanFactory;
import java.util.List;

@Aspect("perthis(execution(* com.xyz.Service.*(..)))")
@Scope("prototype")
class PerThisAspect {
    List state; // bad, not private
}

@Aspect("pertarget(execution(* com.xyz.Service.*(..)))")
@Scope(ConfigurableBeanFactory.SCOPE_PROTOTYPE)
class PerTargetAspect {
    List state; // bad, not private
}

